// Derives vectors/signbytes-kat-v3.1.98.flat.txt from the chain's sign-bytes KAT
// (vectors/signbytes-kat-v3.1.98.json, generated by qorechain-core v3.1.98), for
// the C and Java tests, which read line-based vectors.
//
// Line format (space-separated, "-" = empty field):
//   hybrid_v2 <name> <chainIdHex> <b0Hex> <authInfoHex> <signBytesHex>
// The chain-id is hex-encoded (UTF-8) so non-ASCII ids survive the split.
//
// Run: node scripts/gen-signbytes-kat-flat.mjs
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const vdir = join(dirname(fileURLToPath(import.meta.url)), '..', 'vectors');
const kat = JSON.parse(readFileSync(join(vdir, 'signbytes-kat-v3.1.98.json'), 'utf8'));
const f = (h) => (h === '' ? '-' : h);
const lines = ['# derived from signbytes-kat-v3.1.98.json by scripts/gen-signbytes-kat-flat.mjs'];
for (const v of kat.hybrid_v2) {
  lines.push(['hybrid_v2', v.name, Buffer.from(v.chain_id, 'utf8').toString('hex'),
    f(v.body_without_pqc_ext_hex), f(v.auth_info_hex), v.sign_bytes_hex].join(' '));
}
writeFileSync(join(vdir, 'signbytes-kat-v3.1.98.flat.txt'), lines.join('\n') + '\n');
console.log(`wrote ${kat.hybrid_v2.length} hybrid_v2 vectors`);
